import { GoogleGenAI, Type } from "@google/genai";
import { ExamData } from "./types";

const EXAM_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    mcqs: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.INTEGER },
          question: { type: Type.STRING },
          options: {
            type: Type.OBJECT,
            properties: {
              A: { type: Type.STRING },
              B: { type: Type.STRING },
              C: { type: Type.STRING },
              D: { type: Type.STRING }
            },
            required: ["A", "B", "C", "D"]
          },
          correctAnswer: { type: Type.STRING, enum: ["A", "B", "C", "D"] }
        },
        required: ["id", "question", "options", "correctAnswer"]
      }
    },
    trueFalse: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.INTEGER },
          context: { type: Type.STRING },
          statements: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                text: { type: Type.STRING },
                isCorrect: { type: Type.BOOLEAN }
              },
              required: ["id", "text", "isCorrect"]
            }
          }
        },
        required: ["id", "context", "statements"]
      }
    }
  },
  required: ["title", "mcqs", "trueFalse"]
};

export const generateExam = async (
  grade: number,
  chapter: string,
  extraNotes: string,
  onProgress: (msg: string) => void
): Promise<ExamData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  onProgress("Đang phân tích chương trình và tham khảo nguồn quốc tế...");

  const systemPrompt = `Bạn là một chuyên gia soạn đề kiểm tra Hóa học hàng đầu, am hiểu chương trình GDPT 2018 (3 bộ sách: Kết nối tri thức, Cánh Diều, Chân trời sáng tạo) và các nguồn quốc tế (Khan Academy, Chemistry LibreTexts, ACS, Quizizz).
  Nhiệm vụ: Tạo đề ôn tập chương cho Lớp ${grade}, ${chapter}.

  YÊU CẦU NỘI DUNG:
  1. Loại 1: 50 câu trắc nghiệm MCQ (A, B, C, D).
  2. Loại 2: 25 câu trắc nghiệm Đúng/Sai. Mỗi câu có 1 bối cảnh (tối đa 40 chữ) và 4 lệnh hỏi a), b), c), d).
  3. Bối cảnh gắn liền thực tiễn, giải quyết vấn đề thực tiễn.
  4. Độ khó: Phân hóa từ Nhận biết, Thông hiểu đến Vận dụng cao.
  5. Sử dụng thuật ngữ hóa học IUPAC mới nhất.
  6. Các câu hỏi tham khảo phong cách từ ACS và Khan Academy để tăng tính tư duy.

  GHI CHÚ THÊM TỪ NGƯỜI DÙNG: ${extraNotes || "Không có"}

  ĐỊNH DẠNG ĐẦU RA: Trả về JSON theo schema đã cung cấp.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // Complex STEM task
      contents: "Hãy tạo đề ngay bây giờ.",
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: EXAM_SCHEMA as any,
        thinkingConfig: { thinkingBudget: 32768 } // High budget for quality questions
      },
    });

    const data = JSON.parse(response.text);
    return {
      ...data,
      grade,
      chapter
    };
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import { Document, Packer, Paragraph, TextRun, AlignmentType, HeadingLevel, UnderlineType } from "docx";
import { ExamData, MCQQuestion, TrueFalseQuestion } from "./types";

export const generateExamDoc = async (data: ExamData, isAnswerKey: boolean = false): Promise<Blob> => {
  const children: any[] = [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new TextRun({
          text: `ĐỀ ÔN TẬP KIẾN THỨC HÓA HỌC LỚP ${data.grade}`,
          bold: true,
          size: 28,
        }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new TextRun({
          text: `${data.chapter.toUpperCase()}`,
          bold: true,
          size: 24,
        }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [
        new TextRun({
          text: isAnswerKey ? "(BẢN ĐÁP ÁN)" : "(BẢN ĐỀ THI)",
          italics: true,
          size: 20,
        }),
      ],
    }),
    new Paragraph({ text: "" }),
    new Paragraph({
      children: [
        new TextRun({ text: "PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.", bold: true }),
      ],
    }),
    new Paragraph({
      children: [
        new TextRun({ text: "Thí sinh trả lời từ câu 1 đến câu 50. Mỗi câu hỏi thí sinh chỉ chọn một phương án." }),
      ],
    }),
  ];

  // MCQ Section
  data.mcqs.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { before: 200 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true }),
        new TextRun({ text: q.question }),
      ],
    }));

    const options = ['A', 'B', 'C', 'D'] as const;
    options.forEach(opt => {
      const isCorrect = isAnswerKey && q.correctAnswer === opt;
      children.push(new Paragraph({
        indent: { left: 720 },
        children: [
          new TextRun({
            text: `${opt}. ${q.options[opt]}`,
            italics: isCorrect,
            underline: isCorrect ? { type: UnderlineType.SINGLE } : undefined,
          }),
        ],
      }));
    });
  });

  // True/False Section
  children.push(new Paragraph({ text: "" }));
  children.push(new Paragraph({
    children: [
      new TextRun({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true }),
    ],
  }));
  children.push(new Paragraph({
    children: [
      new TextRun({ text: "Thí sinh trả lời từ câu 1 đến câu 25. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai." }),
    ],
  }));

  data.trueFalse.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { before: 300 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true }),
        new TextRun({ text: q.context }),
      ],
    }));

    q.statements.forEach(s => {
      const isCorrect = isAnswerKey && s.isCorrect;
      children.push(new Paragraph({
        indent: { left: 720 },
        children: [
          new TextRun({
            text: `${s.id}) ${s.text}`,
            italics: isCorrect,
            underline: isCorrect ? { type: UnderlineType.SINGLE } : undefined,
          }),
        ],
      }));
    });
  });

  const doc = new Document({
    sections: [{
      properties: {},
      children: children,
    }],
  });

  return await Packer.toBlob(doc);
};

import React, { useState, useEffect } from 'react';
import { CURRICULUM } from './constants';
import { ExamData, GradeData, Chapter } from './types';
import { generateExam } from './geminiService';
import { generateExamDoc } from './docxGenerator';

const App: React.FC = () => {
  const [selectedGrade, setSelectedGrade] = useState<number>(10);
  const [selectedChapter, setSelectedChapter] = useState<Chapter | null>(null);
  const [extraNotes, setExtraNotes] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [progressMsg, setProgressMsg] = useState<string>('');
  const [examData, setExamData] = useState<ExamData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGradeChange = (grade: number) => {
    setSelectedGrade(grade);
    setSelectedChapter(null);
  };

  const handleCreateExam = async () => {
    if (!selectedChapter) {
      alert("Vui lòng chọn chương!");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setExamData(null);
    setProgressMsg("Bắt đầu khởi tạo dữ liệu...");

    try {
      const data = await generateExam(selectedGrade, selectedChapter.name, extraNotes, setProgressMsg);
      setExamData(data);
      setProgressMsg("Đã tạo đề thành công!");
    } catch (err: any) {
      console.error(err);
      setError("Có lỗi xảy ra trong quá trình tạo đề. Vui lòng thử lại.");
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadDoc = async (type: 'exam' | 'answer') => {
    if (!examData) return;
    const blob = await generateExamDoc(examData, type === 'answer');
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${type === 'exam' ? 'De_Thi' : 'Dap_An'}_Hóa_Học_Lớp_${selectedGrade}_${selectedChapter?.name.replace(/ /g, '_')}.docx`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const reset = () => {
    setExamData(null);
    setError(null);
    setProgressMsg('');
  };

  const activeGradeData = CURRICULUM.find(g => g.grade === selectedGrade);

  return (
    <div className="max-w-5xl mx-auto px-4 py-12">
      <header className="text-center mb-12">
        <h1 className="text-4xl font-extrabold text-blue-900 mb-4">
          Hệ Thống Tạo Đề Ôn Tập Hóa Học 2018
        </h1>
        <p className="text-slate-600 max-w-2xl mx-auto">
          Tạo đề thi chất lượng cao dựa trên 3 bộ sách giáo khoa và các nguồn tài liệu quốc tế uy tín.
          Định dạng chuyên nghiệp với 50 câu MCQ và 25 câu Đúng/Sai.
        </p>
      </header>

      {!examData ? (
        <main className="bg-white rounded-2xl shadow-xl p-8 border border-slate-100">
          <div className="grid md:grid-cols-2 gap-8">
            {/* Selection Area */}
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Chọn Khối Lớp</label>
                <div className="flex gap-2">
                  {[10, 11, 12].map(g => (
                    <button
                      key={g}
                      onClick={() => handleGradeChange(g)}
                      className={`flex-1 py-3 px-4 rounded-lg font-bold transition-all ${
                        selectedGrade === g 
                        ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
                        : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                      }`}
                    >
                      Lớp {g}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Chọn Chương Học</label>
                <div className="max-h-64 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                  {activeGradeData?.chapters.map(ch => (
                    <button
                      key={ch.id}
                      onClick={() => setSelectedChapter(ch)}
                      className={`w-full text-left p-4 rounded-xl border-2 transition-all ${
                        selectedChapter?.id === ch.id
                        ? 'border-blue-500 bg-blue-50'
                        : 'border-slate-100 hover:border-slate-200 bg-white'
                      }`}
                    >
                      <h3 className="font-bold text-slate-800 text-sm">{ch.name}</h3>
                      <p className="text-xs text-slate-500 mt-1">{ch.description}</p>
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* Customization Area */}
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Nội dung cụ thể / Tỉ lệ phân bố</label>
                <textarea
                  value={extraNotes}
                  onChange={(e) => setExtraNotes(e.target.value)}
                  placeholder="Ví dụ: Tập trung vào phản ứng cháy, 30% câu hỏi vận dụng cao, ưu tiên kiến thức từ sách Cánh Diều..."
                  className="w-full h-48 p-4 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none resize-none text-sm transition-all"
                />
              </div>

              <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                <h4 className="text-xs font-bold text-blue-700 uppercase tracking-wider mb-2">Thông tin đề sẽ tạo:</h4>
                <ul className="text-sm text-blue-800 space-y-1">
                  <li>• Phần I: 50 câu MCQ (Lựa chọn A, B, C, D)</li>
                  <li>• Phần II: 25 câu Đúng/Sai (Mỗi câu 4 ý)</li>
                  <li>• Tổng cộng: 150 lệnh hỏi</li>
                  <li>• Thời gian tạo dự kiến: 2-3 phút</li>
                </ul>
              </div>

              <button
                disabled={!selectedChapter || isGenerating}
                onClick={handleCreateExam}
                className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center gap-3 transition-all ${
                  isGenerating 
                  ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                  : 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-xl hover:scale-[1.02] active:scale-[0.98]'
                }`}
              >
                {isGenerating ? (
                  <>
                    <svg className="animate-spin h-5 w-5 text-slate-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Đang tạo đề...
                  </>
                ) : (
                  'BẮT ĐẦU TẠO ĐỀ'
                )}
              </button>

              {isGenerating && (
                <p className="text-center text-sm text-blue-600 animate-pulse font-medium">
                  {progressMsg}
                </p>
              )}

              {error && (
                <p className="text-red-500 text-center text-sm bg-red-50 p-3 rounded-lg border border-red-100">
                  {error}
                </p>
              )}
            </div>
          </div>
        </main>
      ) : (
        <div className="space-y-8 animate-fadeIn">
          {/* Success Result Area */}
          <div className="bg-green-50 border border-green-200 p-8 rounded-2xl flex flex-col md:flex-row items-center justify-between gap-6">
            <div>
              <h2 className="text-2xl font-bold text-green-900">Đã tạo đề hoàn tất!</h2>
              <p className="text-green-700">Đề ôn tập: <span className="font-bold">{selectedChapter?.name}</span> - Lớp {selectedGrade}</p>
            </div>
            <div className="flex flex-wrap gap-3">
              <button
                onClick={() => downloadDoc('exam')}
                className="bg-white text-blue-700 border-2 border-blue-700 px-6 py-3 rounded-xl font-bold hover:bg-blue-50 transition-colors"
              >
                Tải đề thi (.docx)
              </button>
              <button
                onClick={() => downloadDoc('answer')}
                className="bg-blue-700 text-white px-6 py-3 rounded-xl font-bold hover:bg-blue-800 shadow-lg shadow-blue-200 transition-all"
              >
                Tải đáp án (.docx)
              </button>
              <button
                onClick={reset}
                className="bg-slate-700 text-white px-6 py-3 rounded-xl font-bold hover:bg-slate-800 transition-all"
              >
                TẠO ĐỀ MỚI
              </button>
            </div>
          </div>

          {/* Quick Preview */}
          <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-100">
            <div className="bg-slate-800 text-white p-4 flex justify-between items-center">
              <span className="font-bold">Xem trước đề thi (Tóm tắt)</span>
              <span className="text-xs bg-slate-700 px-2 py-1 rounded">Dữ liệu thô từ AI</span>
            </div>
            <div className="p-8 max-h-[600px] overflow-y-auto custom-scrollbar space-y-8 text-slate-800">
              <section>
                <h3 className="text-lg font-bold border-b pb-2 mb-4">PHẦN I: TRẮC NGHIỆM MCQ (50 CÂU)</h3>
                {examData.mcqs.slice(0, 3).map((q, i) => (
                  <div key={i} className="mb-6">
                    <p className="font-semibold mb-2">Câu {q.id}. {q.question}</p>
                    <div className="grid grid-cols-2 gap-2 text-sm ml-4">
                      <p className={q.correctAnswer === 'A' ? 'italic underline font-medium' : ''}>A. {q.options.A}</p>
                      <p className={q.correctAnswer === 'B' ? 'italic underline font-medium' : ''}>B. {q.options.B}</p>
                      <p className={q.correctAnswer === 'C' ? 'italic underline font-medium' : ''}>C. {q.options.C}</p>
                      <p className={q.correctAnswer === 'D' ? 'italic underline font-medium' : ''}>D. {q.options.D}</p>
                    </div>
                  </div>
                ))}
                <p className="text-center italic text-slate-400 py-4 border-t">... và 47 câu tiếp theo ...</p>
              </section>

              <section>
