): Promise<ExamData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  onProgress("Đang phân tích chương trình và tham khảo nguồn quốc tế...");

  const systemPrompt = `Bạn là một chuyên gia soạn đề kiểm tra Hóa học hàng đầu, am hiểu chương trình GDPT 2018 và các nguồn quốc tế (Khan Academy, Chemistry LibreTexts, ACS).
