// Helper component to render chemical formulas and math in the UI
const ChemicalText: React.FC<{ text: string }> = ({ text }) => {
  const parts = text.split(/(\_{.*?\}|\^{.*?\}|\n)/g);

  return (
    <span>
      {parts.map((part, i) => {
        if (part === '\n') return <br key={i} />;
        if (part.startsWith('_{') && part.endsWith('}')) {
          return <sub key={i} className="text-[0.75em] leading-none">{part.slice(2, -1)}</sub>;
        }
        if (part.startsWith('^{') && part.endsWith('}')) {
          return <sup key={i} className="text-[0.75em] leading-none">{part.slice(2, -1)}</sup>;
        }
        return part;
      })}
    </span>
  );
};

