  3. Bối cảnh gắn liền thực tiễn.
  4. Sử dụng thuật ngữ IUPAC.

  GHI CHÚ THÊM: ${extraNotes || "Không có"}

  ĐỊNH DẠNG ĐẦU RA: Trả về JSON theo schema.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: "Hãy tạo đề ngay bây giờ.",
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: EXAM_SCHEMA as any,
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });

    const data = JSON.parse(response.text);
    return { ...data, grade, chapter };
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
