    setIsGenerating(true);
    setError(null);
    setExamData(null);
    setProgressMsg("Bắt đầu khởi tạo dữ liệu...");

    try {
      const data = await generateExam(selectedGrade, selectedChapter.name, extraNotes, setProgressMsg);
      setExamData(data);
      setProgressMsg("Đã tạo đề thành công!");
