  - KHÔNG ĐƯỢC thêm số thứ tự câu vào nội dung text của phát biểu (Ví dụ: SAI: "1. a) Chất X là...", ĐÚNG: "Chất X là...").

  NỘI DUNG: Gắn liền thực tiễn, sử dụng danh pháp IUPAC.
  GHI CHÚ RIÊNG: ${extraNotes || "Không có"}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: "Hãy tạo đề ngay bây giờ.",
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: EXAM_SCHEMA as any,
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });

    const data = JSON.parse(response.text);
    return { ...data, grade, chapter };
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import { Document, Packer, Paragraph, TextRun, AlignmentType, UnderlineType } from "docx";
import { ExamData } from "./types";

/**
 * Parses text with _{sub} and ^{sup} notation into an array of TextRun objects
 */
const parseChemicalText = (text: string, options: { bold?: boolean, italics?: boolean, underline?: boolean, size?: number } = {}): TextRun[] => {
  const parts = text.split(/(\_{.*?\}|\^{.*?\}|\n)/g);
  return parts.filter(p => p !== undefined && p !== "").map(part => {
    if (part === '\n') {
      return new TextRun({ text: " " }); 
    }
    if (part.startsWith('_{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        subscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    if (part.startsWith('^{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        superscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    return new TextRun({
      text: part,
      bold: options.bold,
      italics: options.italics,
      size: options.size,
      underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
    });
  });
};

export const generateExamDoc = async (data: ExamData, isAnswerKey: boolean = false): Promise<Blob> => {
  // Global spacing config to save paper - strictly no space before/after
  const paragraphSpacing = {
    before: 0,
    after: 0,
    line: 240, 
  };

  const children: any[] = [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 120 },
      children: [
        new TextRun({ text: `ĐỀ ÔN TẬP KIẾN THỨC HÓA HỌC LỚP ${data.grade}`, bold: true, size: 28 }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 100 },
      children: [
        new TextRun({ text: `${data.chapter.toUpperCase()}`, bold: true, size: 24 }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 120 },
      children: [
        new TextRun({ text: isAnswerKey ? "(BẢN ĐÁP ÁN - TIẾT KIỆM GIẤY)" : "(BẢN ĐỀ THI)", italics: true, size: 20 }),
      ],
    }),
    new Paragraph({ 
      spacing: paragraphSpacing,
      children: [new TextRun({ text: "PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.", bold: true })] 
    }),
    new Paragraph({ 
      spacing: { ...paragraphSpacing, after: 100 },
      children: [new TextRun({ text: "Mỗi câu hỏi chỉ chọn một phương án đúng." })] 
    }),
  ];

  // MCQ Section
  data.mcqs.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { ...paragraphSpacing, before: index === 0 ? 0 : 60 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true }),
        ...parseChemicalText(q.question)
      ],
    }));

    (['A', 'B', 'C', 'D'] as const).forEach(opt => {
      const isCorrect = isAnswerKey && q.correctAnswer === opt;
      children.push(new Paragraph({
        indent: { left: 420 },
        spacing: paragraphSpacing,
        children: [
          ...parseChemicalText(`${opt}. ${q.options[opt]}`, {
            italics: isCorrect,
            underline: isCorrect
          })
        ],
      }));
    });
  });

  // True/False Section
  children.push(new Paragraph({ 
    spacing: { before: 180, after: 60 }, 
    children: [new TextRun({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true })] 
  }));

  const labelMap = ['a', 'b', 'c', 'd'];

  data.trueFalse.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { ...paragraphSpacing, before: index === 0 ? 0 : 120 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true }),
        ...parseChemicalText(q.context)
      ],
    }));

    q.statements.forEach((s, sIdx) => {
      const isCorrect = isAnswerKey && s.isCorrect;
      const label = labelMap[sIdx] || s.id.toLowerCase();
      children.push(new Paragraph({
        indent: { left: 420 },
        spacing: paragraphSpacing,
        children: [
          ...parseChemicalText(`${label}) ${s.text}`, {
            italics: isCorrect,
            underline: isCorrect
          })
        ],
      }));
    });
  });

  const doc = new Document({
    sections: [{
      properties: {
        page: {
          margin: {
            top: 720, // 0.5 inch
            bottom: 720,
            left: 720,
            right: 720,
          }
        }
      },
      children: children,
    }],
  });

  return await Packer.toBlob(doc);
};

