import { Document, Packer, Paragraph, TextRun, AlignmentType, UnderlineType } from "docx";
import { ExamData } from "./types";

/**
 * Phân tách văn bản chứa _{sub} và ^{sup} thành các TextRun trong Word.
 * Đảm bảo chỉ số trên và chỉ số dưới được render đúng.
 */
const parseChemicalText = (text: string, options: { bold?: boolean, italics?: boolean, underline?: boolean, size?: number, color?: string } = {}): TextRun[] => {
  if (!text) return [];
  // Regex bắt các nhóm _{...} hoặc ^{...}
  const parts = text.split(/(\_{.*?\}|\^{.*?\})/g);

  return parts.filter(p => p !== undefined && p !== "").map(part => {
    if (part.startsWith('_{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        subscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        color: options.color,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    if (part.startsWith('^{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        superscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        color: options.color,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    return new TextRun({
      text: part,
      bold: options.bold,
      italics: options.italics,
      size: options.size,
      color: options.color,
      underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
    });
  });
};

export const generateExamDoc = async (data: ExamData, isAnswerKey: boolean = false): Promise<Blob> => {
  // Cấu hình dãn dòng tối thiểu để tiết kiệm giấy
  const paragraphSpacing = {
    before: 0,
    after: 0,
    line: 220, // Tương đương Single spacing chặt chẽ
  };

  const children: any[] = [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 100 },
      children: [
        new TextRun({ text: `ĐỀ ÔN TẬP HÓA HỌC LỚP ${data.grade}`, bold: true, size: 26 }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 80 },
      children: [
        new TextRun({ text: `${data.chapter.toUpperCase()}`, bold: true, size: 22 }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 100 },
      children: [
        new TextRun({ text: isAnswerKey ? "(ĐÁP ÁN - BẢN TIẾT KIỆM GIẤY)" : "(BẢN ĐỀ THI)", italics: true, size: 18 }),
      ],
    }),
    new Paragraph({ 
      spacing: paragraphSpacing,
      children: [new TextRun({ text: "PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.", bold: true, size: 24 })] 
    }),
    new Paragraph({ 
      spacing: { ...paragraphSpacing, after: 60 },
      children: [new TextRun({ text: "Mỗi câu hỏi chỉ chọn một phương án đúng.", size: 22 })] 
    }),
  ];

  // MCQ Section
  data.mcqs.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { ...paragraphSpacing, before: (index === 0 || isAnswerKey) ? 0 : 60 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true, size: 24 }),
        ...parseChemicalText(q.question, { size: 24 })
      ],
    }));

    (['A', 'B', 'C', 'D'] as const).forEach(opt => {
      const isCorrect = isAnswerKey && q.correctAnswer === opt;
      children.push(new Paragraph({
        indent: { left: 420 },
        spacing: paragraphSpacing,
        children: [
          ...parseChemicalText(`${opt}. ${q.options[opt]}`, {
            size: 24,
            // Theo yêu cầu: Không in đậm đáp án, dùng gạch chân để nhận biết trong bản đáp án
            underline: isCorrect,
            italics: isCorrect,
            color: isCorrect ? "0000FF" : undefined
          })
        ],
      }));
    });
  });

  // True/False Section
  children.push(new Paragraph({ 
    spacing: { before: 180, after: 40 }, 
    children: [new TextRun({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true, size: 24 })] 
  }));

  const labelMap = ['a', 'b', 'c', 'd'];

  data.trueFalse.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { ...paragraphSpacing, before: (index === 0 || isAnswerKey) ? 0 : 100 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true, size: 24 }),
        ...parseChemicalText(q.context, { size: 24 })
      ],
    }));

    q.statements.forEach((s, sIdx) => {
      const isCorrect = isAnswerKey && s.isCorrect;
      const label = labelMap[sIdx] || 'a';
      children.push(new Paragraph({
        indent: { left: 420 },
        spacing: paragraphSpacing,
        children: [
          ...parseChemicalText(`${label}) ${s.text}`, {
            size: 24,
            // Theo yêu cầu: Không in đậm đáp án
            underline: isCorrect,
            italics: isCorrect,
            color: isCorrect ? "0000FF" : undefined
          })
        ],
      }));
    });
  });

  const doc = new Document({
    sections: [{
      properties: {
        page: {
          margin: {
            top: 400,    // ~0.7cm
            bottom: 400, // ~0.7cm
            left: 567,   // 1cm
            right: 400,  // ~0.7cm
          }
        }
      },
      children: children,
    }],
  });

  return await Packer.toBlob(doc);
};

