import { Document, Packer, Paragraph, TextRun, AlignmentType, UnderlineType } from "docx";
import { ExamData } from "./types";

/**
 * Phân tách văn bản chứa _{sub} và ^{sup} thành các TextRun trong Word.
 */
const parseChemicalText = (text: string, options: { bold?: boolean, italics?: boolean, underline?: boolean, size?: number, color?: string } = {}): TextRun[] => {
  if (!text) return [];
  const parts = text.split(/(\_{.*?\}|\^{.*?\})/g);

  return parts.filter(p => p !== undefined && p !== "").map(part => {
    if (part.startsWith('_{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        subscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        color: options.color,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    if (part.startsWith('^{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        superscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        color: options.color,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    return new TextRun({
      text: part,
      bold: options.bold,
      italics: options.italics,
      size: options.size,
      color: options.color,
      underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
    });
  });
};

export const generateExamDoc = async (data: ExamData, isAnswerKey: boolean = false): Promise<Blob> => {
  const paragraphSpacing = { before: 0, after: 0, line: 220 };

  const children: any[] = [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 120 },
      children: [
        new TextRun({ 
          text: `ĐỀ ÔN TẬP HÓA HỌC LỚP ${data.grade} - ${data.unitName || data.chapter}`, 
          bold: true, 
          size: 26 
        }),
      ],
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { after: 120 },
      children: [
        new TextRun({ 
          text: isAnswerKey ? "(BẢN ĐÁP ÁN TIẾT KIỆM GIẤY)" : "(BẢN ĐỀ THI)", 
          italics: true, 
          size: 18 
        }),
      ],
    }),
    new Paragraph({ 
      spacing: paragraphSpacing,
      children: [new TextRun({ text: "PHẦN I. Câu trắc nghiệm nhiều phương án lựa chọn.", bold: true, size: 24 })] 
    }),
    new Paragraph({ 
      spacing: { ...paragraphSpacing, after: 60 },
      children: [new TextRun({ text: "Mỗi câu hỏi chỉ chọn một phương án đúng.", size: 22 })] 
    }),
  ];

  // MCQ Section
  data.mcqs.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { ...paragraphSpacing, before: (index === 0 || isAnswerKey) ? 0 : 80 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true, size: 22 }),
        ...parseChemicalText(q.question, { size: 22 })
      ],
    }));

    (['A', 'B', 'C', 'D'] as const).forEach(opt => {
      const isCorrect = isAnswerKey && q.correctAnswer === opt;
      children.push(new Paragraph({
        indent: { left: 420 },
        spacing: paragraphSpacing,
        children: [
          ...parseChemicalText(`${opt}. ${q.options[opt]}`, {
            size: 22,
            bold: false, // TUYỆT ĐỐI KHÔNG IN ĐẬM ĐÁP ÁN THEO YÊU CẦU
            underline: isCorrect,
            color: isCorrect ? "0000FF" : undefined
          })
        ],
      }));
    });
  });

  // True/False Section
  children.push(new Paragraph({ 
    spacing: { before: 180, after: 40 }, 
    children: [new TextRun({ text: "PHẦN II. Câu trắc nghiệm đúng sai.", bold: true, size: 24 })] 
  }));

  const labelMap = ['a', 'b', 'c', 'd'];

  data.trueFalse.forEach((q, index) => {
    children.push(new Paragraph({
      spacing: { ...paragraphSpacing, before: (index === 0 || isAnswerKey) ? 0 : 100 },
      children: [
        new TextRun({ text: `Câu ${index + 1}. `, bold: true, size: 22 }),
        ...parseChemicalText(q.context, { size: 22 })
      ],
    }));

    q.statements.forEach((s, sIdx) => {
      const isCorrect = isAnswerKey && s.isCorrect;
      const label = labelMap[sIdx] || 'a';
      children.push(new Paragraph({
        indent: { left: 420 },
        spacing: paragraphSpacing,
        children: [
          ...parseChemicalText(`${label}) ${s.text}`, {
            size: 22,
            bold: false, // TUYỆT ĐỐI KHÔNG IN ĐẬM ĐÁP ÁN
            underline: isCorrect,
            color: isCorrect ? "0000FF" : undefined
          })
        ],
      }));
    });
  });

  const doc = new Document({
    sections: [{
      properties: {
        page: {
          margin: { top: 400, bottom: 400, left: 567, right: 400 }
        }
      },
      children: children,
    }],
  });

  return await Packer.toBlob(doc);
};

import { GoogleGenAI, Type } from "@google/genai";
import { ExamData } from "./types";

const EXAM_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    mcqs: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.INTEGER },
          question: { type: Type.STRING },
          options: {
            type: Type.OBJECT,
            properties: {
              A: { type: Type.STRING },
              B: { type: Type.STRING },
              C: { type: Type.STRING },
              D: { type: Type.STRING }
            },
            required: ["A", "B", "C", "D"]
          },
          correctAnswer: { type: Type.STRING, enum: ["A", "B", "C", "D"] }
        },
        required: ["id", "question", "options", "correctAnswer"]
      }
    },
    trueFalse: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.INTEGER },
          context: { type: Type.STRING },
          statements: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                text: { type: Type.STRING },
                isCorrect: { type: Type.BOOLEAN }
              },
              required: ["id", "text", "isCorrect"]
            }
          }
        },
        required: ["id", "context", "statements"]
      }
    }
  },
  required: ["title", "mcqs", "trueFalse"]
};

export const generateExam = async (
  grade: number,
  chapter: string,
  extraNotes: string,
  unitName: string | null,
  pdfBase64: string | null,
  onProgress: (msg: string) => void
): Promise<ExamData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  onProgress(pdfBase64 ? "Đang đọc tài liệu PDF và phân tích kiến thức theo tỉ lệ 40-30-30..." : "Đang chuẩn bị đề thi 40% Biết, 30% Hiểu, 30% Vận dụng...");

  const systemPrompt = `Bạn là chuyên gia khảo thí Hóa học. Tạo đề ôn tập cho Lớp ${grade}, ${chapter}${unitName ? `, Module: ${unitName}` : ''}.

  QUY TẮC NỘI DUNG (CỰC KỲ QUAN TRỌNG):
  1. TỈ LỆ NHẬN THỨC: Mỗi phần phải đảm bảo 40% câu hỏi ở mức độ BIẾT, 30% mức độ HIỂU, 30% mức độ VẬN DỤNG.
  2. PHẦN I (50 câu MCQ):
     - Phần dẫn câu hỏi (question stem) phải DÀI ÍT NHẤT 20 CHỮ. Không được đặt câu hỏi quá ngắn gọn.
     - Đánh số từ Câu 1 đến Câu 50.
  3. PHẦN II (25 câu Đúng/Sai):
     - Bối cảnh (context) cho mỗi câu phải DÀI ÍT NHẤT 40 CHỮ để cung cấp đủ dữ kiện thực tiễn hoặc lý thuyết chuyên sâu.
     - Mỗi câu có 4 phát biểu id 'a', 'b', 'c', 'd'.

  ĐỊNH DẠNG HÓA HỌC:
  - Chỉ số dưới: dùng _{...}. Ví dụ: H_{2}SO_{4}
  - Chỉ số trên/Điện tích: dùng ^{...}. Ví dụ: Fe^{3+}
  - Luôn dùng IUPAC.

  ${pdfBase64 ? "Ưu tiên tối đa nội dung từ file PDF đính kèm." : "Dựa trên chương trình GDPT 2018."}
  Ghi chú bổ sung: ${extraNotes || "Không có"}`;

  const contents: any[] = [{ text: "Hãy tạo đề thi ngay bây giờ. Đảm bảo đúng số lượng 50 câu MCQ và 25 câu Đúng/Sai với độ dài văn bản như yêu cầu." }];

  if (pdfBase64) {
    contents.push({
      inlineData: {
        mimeType: "application/pdf",
        data: pdfBase64
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview", // Sử dụng model mạnh nhất cho yêu cầu phức tạp
      contents: { parts: contents as any },
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: EXAM_SCHEMA as any,
        thinkingConfig: { thinkingBudget: 32768 } // Cho phép AI suy nghĩ kỹ để đảm bảo độ dài văn bản
      },
    });

    const data = JSON.parse(response.text);
    return { ...data, grade, chapter, unitName };
  } catch (error) {
    console.error("Gemini Error:", error);
    throw error;
  }
};

import { Document, Packer, Paragraph, TextRun, AlignmentType, UnderlineType } from "docx";
import { ExamData } from "./types";

const parseChemicalText = (text: string, options: { bold?: boolean, italics?: boolean, underline?: boolean, size?: number, color?: string } = {}): TextRun[] => {
  if (!text) return [];
  const parts = text.split(/(\_{.*?\}|\^{.*?\})/g);

  return parts.filter(p => p !== undefined && p !== "").map(part => {
    if (part.startsWith('_{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        subscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        color: options.color,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    if (part.startsWith('^{') && part.endsWith('}')) {
      return new TextRun({
        text: part.slice(2, -1),
        superscript: true,
        bold: options.bold,
        italics: options.italics,
        size: options.size,
        color: options.color,
        underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
      });
    }
    return new TextRun({
      text: part,
      bold: options.bold,
      italics: options.italics,
      size: options.size,
      color: options.color,
      underline: options.underline ? { type: UnderlineType.SINGLE } : undefined,
    });
  });
};

